// Verify HMAC-SHA256 signature produced by ZaloCRM webhook-service.ts.
// Using require() + explicit NODE_FUNCTION_ALLOW_BUILTIN=crypto in n8n env
// because ES-module `import` is rejected by n8n's Code-node VM by default.
const crypto = require('crypto');
const secret    = $env.ZALOCRM_WEBHOOK_SECRET;
const signature = $input.first().headers['x-webhook-signature'];
const event     = $input.first().headers['x-webhook-event'];
const raw       = $input.first().body;  // from rawBody option
const rawStr    = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!secret || !signature) throw new Error('missing signature');
const expected  = crypto.createHmac('sha256', secret).update(rawStr).digest('hex');
const expBuf    = Buffer.from(expected);
const sigBuf    = Buffer.from(signature);
if (expBuf.length !== sigBuf.length || !crypto.timingSafeEqual(expBuf, sigBuf)) {
  throw new Error('bad_signature');
}
const parsed    = typeof raw === 'string' ? JSON.parse(raw) : raw;
return [{ json: { event, data: parsed.data, timestamp: parsed.timestamp } }];

// Normalize Vietnamese text for intent caching.
// Payload shape guaranteed by ZaloCRM message-handler.ts:
//   { messageId, conversationId, zaloAccountId, threadId, threadType,
//     senderType, senderUid, senderName, contactId, content, contentType, sentAt }
const crypto = require('crypto');
const d = $json.data || {};
const text = String(d.content || '').normalize('NFC').toLowerCase().replace(/\s+/g, ' ').trim();
const hash = crypto.createHash('sha256').update(text).digest('hex');
return [{ json: {
  orgId: $env.ZALOCRM_ORG_ID,
  channel: 'zalo',
  convKey: `zalo:${d.conversationId || d.threadId}`,
  contactId: d.contactId || null,
  conversationId: d.conversationId,
  zaloAccountId: d.zaloAccountId,
  threadId: d.threadId,
  threadType: d.threadType || 'user',
  senderType: d.senderType,
  contactName: d.senderName || 'Khách',
  raw: d,
  text,
  messageHash: hash
}}];

