const cached = $('Intent cache GET').first().json?.value;
const usage  = $input.first().json?.usage || {};
const raw    = cached || ($input.first().json.choices?.[0]?.message?.content ?? '{}');
let parsed;
try { parsed = JSON.parse(raw); } catch { parsed = { intent: 'other', confidence: 0, urgency: 'low', leadScore: 0, language: 'vi', needsHuman: true, reason: 'parse_error' }; }
const ctx = $('Normalize + hash').first().json;
return [{ json: {
  ...ctx,
  intent:     parsed.intent,
  confidence: parsed.confidence,
  urgency:    parsed.urgency,
  leadScore:  parsed.leadScore,
  language:   parsed.language || 'vi',
  needsHuman: parsed.needsHuman || parsed.intent === 'complaint' || parsed.confidence < 0.7,
  reason:     parsed.reason,
  fromCache:  Boolean(cached),
  tokensIn:   usage.prompt_tokens || 0,
  tokensOut:  usage.completion_tokens || 0,
  model:      $input.first().json.model || 'cached'
}}];

