const txt = ($input.first().json.choices?.[0]?.message?.content || '').trim().slice(0, 500);
const intent = $('Parse intent').first().json;
const shadow = ($env.CSKH_SHADOW_MODE ?? 'true') === 'true';
return [{ json: { reply: txt, shadow, ...intent } }];

// Normalize the log record across the three upstream branches (handoff,
// live auto-reply, shadow). Each branch enters with a different $json shape
// (Telegram API response / ZaloCRM send response / Shape reply object), so we
// reconstruct the record from Parse intent + Shape reply via node references,
// never from $json.
const pi   = $('Parse intent').first().json;
const norm = $('Normalize + hash').first().json;

// Handoff path is deterministic from Parse intent: either the classifier asked
// for human, or intent is lead_qualified. In both cases Shape reply did NOT run.
const isHandoff = pi.needsHuman === true || pi.intent === 'lead_qualified';

let shadow = true;
let reply  = null;
if (!isHandoff) {
  try {
    const sr = $('Shape reply + shadow flag').first()?.json;
    if (sr) {
      shadow = sr.shadow !== false;        // default to shadow when unset
      reply  = (sr.reply || '').toString() || null;
    }
  } catch (_) {
    // Shape reply did not execute in this run; keep defaults.
  }
}

const actionTaken = isHandoff
  ? 'handoff'
  : (shadow ? 'shadow' : 'auto_reply');

return [{ json: {
  orgId:       norm.orgId,
  channel:     'zalo',
  convKey:     norm.convKey,
  messageHash: norm.messageHash,
  intent:      pi.intent,
  confidence:  pi.confidence,
  leadScore:   pi.leadScore,
  urgency:     pi.urgency,
  language:    pi.language || 'vi',
  actionTaken,
  botDraft:    reply,
  actualReply: (!isHandoff && !shadow) ? reply : null,
  model:       pi.model,
  tokensIn:    pi.tokensIn,
  tokensOut:   pi.tokensOut
}}];
